-- SQLite evaluates RLS at the API layer. Membership subqueries are supported in
-- USING clauses and UPDATE checks, but not in INSERT WITH CHECK. Every insert
-- therefore binds the authenticated creator/owner plus a status or role
-- attestation backed by a composite foreign key to workspace_members.

alter table public.workspaces enable row level security;
create policy workspaces_select on public.workspaces for select to authenticated
using (owner_id = auth.uid() or exists (select 1 from workspace_members where workspace_members.workspace_id = workspaces.id and workspace_members.user_id = auth.uid() and workspace_members.status = 'active'));
create policy workspaces_insert on public.workspaces for insert to authenticated
with check (owner_id = auth.uid() and created_by = auth.uid());
create policy workspaces_update on public.workspaces for update to authenticated
using (owner_id = auth.uid()) with check (owner_id = auth.uid());
create policy workspaces_delete on public.workspaces for delete to authenticated using (owner_id = auth.uid());

alter table public.profiles enable row level security;
create policy profiles_select on public.profiles for select to authenticated using (
  id = auth.uid() or exists (
    select 1 from workspace_members
    where workspace_members.user_id = profiles.id
      and workspace_members.status = 'active'
      and workspace_members.workspace_id in (
        select workspace_id from workspace_members
        where workspace_members.user_id = auth.uid()
          and workspace_members.status = 'active'
      )
  )
);
create policy profiles_insert on public.profiles for insert to authenticated with check (id = auth.uid());
create policy profiles_update on public.profiles for update to authenticated using (id = auth.uid()) with check (id = auth.uid());
create policy profiles_delete on public.profiles for delete to authenticated using (id = auth.uid());

alter table public.workspace_members enable row level security;
create policy workspace_members_select on public.workspace_members for select to authenticated
using (user_id = auth.uid() or exists (select 1 from workspaces where workspaces.id = workspace_members.workspace_id and workspaces.owner_id = auth.uid()));
create policy workspace_members_insert on public.workspace_members for insert to authenticated
with check (workspace_owner_id = auth.uid() and created_by = auth.uid());
create policy workspace_members_update on public.workspace_members for update to authenticated
using (workspace_owner_id = auth.uid())
with check (workspace_owner_id = auth.uid());
create policy workspace_members_delete on public.workspace_members for delete to authenticated
using (workspace_owner_id = auth.uid());

