create policy teams_select on public.teams for select to authenticated using (exists (select 1 from workspace_members where workspace_members.workspace_id = teams.workspace_id and workspace_members.user_id = auth.uid() and workspace_members.status = 'active'));
create policy teams_insert on public.teams for insert to authenticated with check (created_by = auth.uid() and created_by_role in ('owner','admin') and created_by_status = 'active');
create policy teams_update on public.teams for update to authenticated using (exists (select 1 from workspace_members where workspace_members.workspace_id = teams.workspace_id and workspace_members.user_id = auth.uid() and workspace_members.role in ('owner','admin') and workspace_members.status = 'active')) with check (exists (select 1 from workspace_members where workspace_members.workspace_id = teams.workspace_id and workspace_members.user_id = auth.uid() and workspace_members.role in ('owner','admin') and workspace_members.status = 'active'));
create policy teams_delete on public.teams for delete to authenticated using (exists (select 1 from workspace_members where workspace_members.workspace_id = teams.workspace_id and workspace_members.user_id = auth.uid() and workspace_members.role in ('owner','admin') and workspace_members.status = 'active'));

