-- Storage paths use <workspace>/<user>/<entity>/<file>. INSERT avoids a
-- membership subquery by binding the second path component to auth.uid().
create policy crm_files_select on storage.objects for select to authenticated
using (bucket_id = 'crm-files' and owner_id = auth.uid()::text);
create policy crm_files_insert on storage.objects for insert to authenticated
with check (bucket_id = 'crm-files' and owner_id = auth.uid()::text and (storage.foldername(name))[2] = auth.uid()::text);
create policy crm_files_update on storage.objects for update to authenticated
using (bucket_id = 'crm-files' and owner_id = auth.uid()::text)
with check (bucket_id = 'crm-files' and owner_id = auth.uid()::text and (storage.foldername(name))[2] = auth.uid()::text);
create policy crm_files_delete on storage.objects for delete to authenticated
using (bucket_id = 'crm-files' and owner_id = auth.uid()::text);
